// The dispatcher passes the webhook item through: { body: { table, recordId } }.
// A manual call may pass { leaseId } instead. No id at all -> search every lease sitting at Prepare.
const AT = 'https://api.airtable.com/v0/%%VAO::BASE_ID%%/%%VAO::TBL::Leases%%';
const j = $json || {};
const id = String(((j.body || {}).recordId) || j.recordId || j.leaseId || '').trim();
const q = String.fromCharCode(39);
return [{ json: {
  url: id ? AT + '/' + id : AT + '?filterByFormula=' + encodeURIComponent('{Security Deposit Disposition}=' + q + 'Prepare' + q) + '&pageSize=50&fields%5B0%5D=Lease%20Name&fields%5B1%5D=Security%20Deposit%20Disposition',
  single: !!id
} }];

// Only leases whose field is exactly Prepare go on. Everything else (the watcher also fires when
// the flow itself writes Awaiting Approval, or when the task automation writes Full) ends here.
const r = $json || {};
const recs = Array.isArray(r.records) ? r.records : (r.id ? [r] : []);
const out = [];
for (const rec of recs) {
  const f = rec.fields || {};
  if (String(f['Security Deposit Disposition'] || '') !== 'Prepare') continue;
  out.push({ json: { leaseId: rec.id, leaseName: String(f['Lease Name'] || rec.id) } });
}
return out;
